@@ -5,18 +5,58 @@ export interface Job {
   claimedBy: string | null;
 }

-const jobs = new Map<string, Job>();
+interface Datastore {
+  getJobs(): Promise<Job[]>;
+  claimJob(jobId: string, worker: string): Promise<boolean>;
+  finishJob(jobId: string): Promise<void>;
+}
+
+const createMemoryDatastore = (): Datastore & { jobs: Map<string, Job> } => {
+  const jobs = new Map<string, Job>();
+  return {
+    jobs,
+    getJobs: async () => Array.from(jobs.values()),
+    claimJob: async (jobId: string, worker: string) => {
+      const job = jobs.get(jobId);
+      if (job === undefined || job.done || job.claimedBy !== null) {
+        return false;
+      }
+      job.claimedBy = worker;
+      return true;
+    },
+    finishJob: async (jobId: string) => {
+      const job = jobs.get(jobId);
+      if (job !== undefined) {
+        job.done = true;
+      }
+    },
+  };
+};
+
+let datastore: any = createMemoryDatastore();
+
+export const setDatastore = (ds: Datastore): void => {
+  datastore = ds;
+};
+
+export const initializeJob = (job: Job): void => {
+  if (datastore.jobs instanceof Map) {
+    datastore.jobs.set(job.id, job);
+  }
+};

-export const claim = (now: number, worker: string): Job | null => {
-  for (const job of jobs.values()) {
+export const claim = async (now: number, worker: string): Promise<Job | null> => {
+  const jobs = await datastore.getJobs();
+  for (const job of jobs) {
     if (job.done || job.claimedBy !== null || job.runAt > now) continue;
-    job.claimedBy = worker;
-    return job;
+    const claimed = await datastore.claimJob(job.id, worker);
+    if (claimed) {
+      return job;
+    }
   }
   return null;
 };

-export const finish = (id: string): void => {
-  const job = jobs.get(id);
-  if (job !== undefined) job.done = true;
+export const finish = async (id: string): Promise<void> => {
+  await datastore.finishJob(id);
 };
